import assert from 'node:assert/strict';
import {testServer} from '../../packages/server/test/helpers.js';
export async function smoke(ctx) {
  const {api,request,signup,check,ids}=ctx;
  await check('people organization and team persist with owner membership',async()=>{
    const organization=(await api('POST','/orgs',{name:'Acceptance Crew'})).organization;
    ids.orgId=organization.id;
    assert.equal(organization.role,'owner');
    const renamed=(await api('PATCH','/orgs/'+ids.orgId,{name:'Acceptance Team'})).organization;
    assert.equal(renamed.name,'Acceptance Team');
    const team=(await api('POST','/orgs/'+ids.orgId+'/teams',{name:'Delivery',description:'Acceptance team'})).team;
    ids.teamId=team.id;
    assert.equal(team.orgId,ids.orgId);
    const owner=ctx.clients.owner.user;
    await api('POST','/teams/'+ids.teamId+'/members',{userId:owner.id});
    const members=(await api('GET','/teams/'+ids.teamId+'/members')).items;
    assert.equal(members[0].userId,owner.id);
  });
  await check('people member and guest roles enforce administrative denials',async()=>{
    const suffix=Date.now();
    const member=await signup('member',{name:'Acceptance Member',email:`member-${suffix}@crew.test`,password:'acceptance member password'});
    const guest=await signup('guest',{name:'Acceptance Guest',email:`guest-${suffix}@crew.test`,password:'acceptance guest password'});
    const invitation=(await api('POST','/orgs/'+ids.orgId+'/invitations',{email:member.email,role:'member'})).invitation;
    ids.invitationId=invitation.id;
    const outbox=(await api('GET','/me/outbox?kind=invite',undefined,'member')).items;
    const token=decodeURIComponent(outbox.find(item=>item.payload.invitationId===invitation.id).payload.link.split('token=')[1]);
    const accepted=await api('POST','/invitations/accept',{token},'member');
    assert.equal(accepted.membership.userId,member.id);assert.equal(accepted.membership.role,'member');
    assert.equal((await request('POST','/invitations/accept',{token},{actor:'member'})).status,409);
    await api('POST','/orgs/'+ids.orgId+'/members',{userId:guest.id,role:'guest'});
    await api('POST','/teams/'+ids.teamId+'/members',{userId:member.id});
    assert.equal((await request('PATCH','/orgs/'+ids.orgId,{name:'Denied'},{actor:'member'})).status,403);
    assert.equal((await request('POST','/orgs/'+ids.orgId+'/teams',{name:'Denied'},{actor:'guest'})).status,403);
    const owner=ctx.clients.owner.user;
    assert.equal((await request('PATCH','/orgs/'+ids.orgId+'/members/'+owner.id,{role:'member'})).status,409);
  });
  await check('people session revoke and password change/reset preserve account custody',async()=>{
    const owner=ctx.clients.owner;
    const originalCookie=owner.cookie;
    await api('POST','/auth/login',{email:owner.email,password:owner.password});
    const sessions=(await api('GET','/auth/sessions')).items;
    const previous=sessions.find(item=>!item.current);assert(previous);
    await api('DELETE','/auth/sessions/'+previous.id);
    ctx.clients.revoked={cookie:originalCookie};
    assert.equal((await request('GET','/me',undefined,{actor:'revoked'})).status,401);
    delete ctx.clients.revoked;
    const changedPassword='acceptance changed owner password';
    await api('POST','/auth/password/change',{currentPassword:owner.password,password:changedPassword});
    ctx.clients.owner.password=changedPassword;
    assert.equal((await api('GET','/me')).user.id,owner.user.id);
    await api('POST','/auth/password/reset/request',{email:owner.email});
    const reset=(await api('GET','/me/outbox?kind=reset')).items[0];
    const token=decodeURIComponent(reset.payload.link.split('token=')[1]);
    const password='acceptance reset owner password';
    await api('POST','/auth/password/reset',{token,password});
    assert.equal((await request('GET','/me')).status,401);
    assert.equal((await request('POST','/auth/password/reset',{token,password})).status,422);
    ctx.clients.owner.password=password;
    await api('POST','/auth/login',{email:owner.email,password});
    assert.equal((await api('GET','/me')).user.id,owner.user.id);
  });
  await check('people scoped token, immediate revocation, audit and real CLI commands',async()=>{
    const created=await api('POST','/tokens',{name:'Acceptance CLI',scopes:['*'],expiresInDays:30});
    ids.ownerTokenId=created.personalToken.id;
    assert.equal(created.personalToken.state,'active');
    ctx.clients.owner.token=created.token;
    assert.equal((await api('GET','/me')).auth.kind,'token');
    const listed=(await api('GET','/tokens')).items.find(token=>token.id===ids.ownerTokenId);
    assert.equal(listed.name,'Acceptance CLI');assert(!Object.hasOwn(listed,'token'));assert(listed.lastUsedAt);
    const limited=await api('POST','/tokens',{name:'Restricted proof',scopes:['self:read']});
    ctx.clients.scoped={token:limited.token};
    assert.equal((await api('GET','/me',undefined,'scoped')).user.id,ctx.clients.owner.user.id);
    assert.equal((await request('GET','/orgs',undefined,{actor:'scoped'})).status,403);
    assert.equal((await request('GET','/me/outbox',undefined,{actor:'scoped'})).status,403);
    await api('DELETE','/tokens/'+limited.personalToken.id);
    assert.equal((await request('GET','/me',undefined,{actor:'scoped'})).status,401);
    delete ctx.clients.scoped;
    assert.equal((await ctx.cli(['whoami'])).auth.kind,'token');
    assert.equal((await ctx.cli(['org','show',ids.orgId])).organization.name,'Acceptance Team');
    assert((await ctx.cli(['team','list','--org',ids.orgId])).items.some(team=>team.id===ids.teamId));
    assert((await ctx.cli(['invite','list','--org',ids.orgId,'--state','accepted'])).items.some(invite=>invite.id===ids.invitationId));
    assert((await ctx.cli(['token','list'])).items.some(token=>token.id===ids.ownerTokenId));
    const audit=(await api('GET','/orgs/'+ids.orgId+'/audit?entityType=invitation&action=accepted')).items;
    assert(audit.some(event=>event.entityId===ids.invitationId&&event.after.acceptedBy===ctx.clients.member.user.id));
    assert(!JSON.stringify(audit).includes(created.token));
  });
}
export async function restart(ctx) {
  await ctx.check('people organization team and roles survive restart',async()=>{
    assert.equal((await ctx.cli(['whoami'])).auth.kind,'token');
    const tokens=(await ctx.api('GET','/tokens')).items;
    assert(tokens.some(token=>token.id===ctx.ids.ownerTokenId&&token.state==='active'));
    const security=(await ctx.api('GET','/me/audit?entityType=api_token')).items;
    assert(security.some(event=>event.entityId===ctx.ids.ownerTokenId));
    const organization=(await ctx.api('GET','/orgs/'+ctx.ids.orgId)).organization;
    assert.equal(organization.name,'Acceptance Team');
    const invites=(await ctx.api('GET','/orgs/'+ctx.ids.orgId+'/invitations?state=accepted')).items;
    assert(invites.some(invite=>invite.id===ctx.ids.invitationId&&invite.acceptedBy===ctx.clients.member.user.id));
    const team=(await ctx.api('GET','/teams/'+ctx.ids.teamId)).team;
    assert.equal(team.name,'Delivery');
    const members=(await ctx.api('GET','/orgs/'+ctx.ids.orgId+'/members')).items;
    assert(members.some(m=>m.userId===ctx.clients.guest.user.id&&m.role==='guest'));
    assert(members.some(m=>m.userId===ctx.clients.member.user.id&&m.role==='member'));
    const teamMembers=(await ctx.api('GET','/teams/'+ctx.ids.teamId+'/members')).items;
    assert(teamMembers.some(m=>m.userId===ctx.clients.member.user.id));
  });
}
export async function audit({checks}) {
  const server=await testServer();
  try {
    const publicRoutes=new Set(['GET /api/v1/health','POST /api/v1/auth/signup','POST /api/v1/auth/login',
      'POST /api/v1/invitations/preview','POST /api/v1/auth/password/reset/request','POST /api/v1/auth/password/reset']);
    const routes=[];
    for(const layer of server.ctx.app._router.stack) {
      if(!layer.route||!layer.route.path.startsWith('/api/v1'))continue;
      for(const method of Object.keys(layer.route.methods)) {
        const signature=method.toUpperCase()+' '+layer.route.path;
        const isPublic=publicRoutes.has(signature);
        if(!isPublic) {
          const url=server.url+layer.route.path.replace(/:[A-Za-z]+/g,'missing-id');
          const response=await fetch(url,{method:method.toUpperCase(),headers:{'content-type':'application/json'},body:method==='get'?undefined:'{}',signal:AbortSignal.timeout(3000)});
          assert.equal(response.status,401,'Unauthenticated route must deny: '+signature);
        }
        routes.push({method:method.toUpperCase(),path:layer.route.path,public:isPublic});
      }
    }
    assert(routes.some(route=>route.path.includes('sprints')));assert(routes.some(route=>route.path.includes('attachments')));
    checks.push({name:'All currently registered API routes deny unauthenticated access except explicit public auth/link entrypoints',ok:true,routeCount:routes.length,routes});
    const integratedRoutes=['GET /api/v1/search/catalog','GET /api/v1/search/suggestions','GET /api/v1/activity',
      'GET /api/v1/subscriptions','GET /api/v1/notifications','POST /api/v1/notifications/mark',
      'GET /api/v1/digests','GET /api/v1/filters/:filterId/search','GET /api/v1/dashboard',
      'GET /api/v1/projects/:projectId/export','POST /api/v1/orgs/:orgId/import','GET /api/v1/insight/options',
      'GET /api/v1/projects/:projectId/issue-options','GET /api/v1/sprints/:sprintId/candidates',
      'GET /api/v1/sprints/:sprintId/scope','GET /api/v1/sprints/:sprintId/carry-targets','GET /api/v1/events'];
    const signatures=new Set(routes.map(route=>route.method+' '+route.path));
    for(const signature of integratedRoutes)assert(signatures.has(signature),'Reviewed integrated route must exist: '+signature);
    checks.push({name:'Final integrated people review includes insight delivery, private state, transfer, work candidates and live SSE',ok:true,
      protectedRouteCount:routes.filter(route=>!route.public).length,publicRouteCount:routes.filter(route=>route.public).length,
      policyTests:['server/test/people-delivery.test.js','server/test/people-integration.test.js','server/test/insight-sse.test.js','cli/test/people-boundaries.test.js'],
      note:'This runtime census proves registration and anonymous denial. Dedicated package HTTP/CLI tests separately prove positive access, scope/role/project/user/team boundaries and revocation cleanup.'});
  }finally{await server.close();}
}
